    private static void registerBoundary(Object listener){MinecraftForge.EVENT_BUS.register(listener);EXTRA_LISTENERS.add(listener);}
    private static final class EmberPublicationBoundary{
        final GameTestHelper h;final AshBoneWingUnit aba,stopped,recursive;boolean abaSeen,stopSeen,recurseSeen;SkillResult nested;RuntimeException failure;
        EmberPublicationBoundary(GameTestHelper h,AshBoneWingUnit aba,AshBoneWingUnit stopped,AshBoneWingUnit recursive){this.h=h;this.aba=aba;this.stopped=stopped;this.recursive=recursive;}
        @SubscribeEvent(priority=EventPriority.HIGHEST) public void join(EntityJoinLevelEvent event){if(!(event.getEntity() instanceof EmberLandingProjectile shot))return;try{if(shot.getOwner()==aba&&!abaSeen){abaSeen=true;String owner=aba.getOwnerName();aba.setOwnerName(owner+"Temporary");aba.setOwnerName(owner);}else if(shot.getOwner()==stopped&&!stopSeen){stopSeen=true;order(h,stopped,UnitAction.STOP,null,BlockPos.ZERO);}else if(shot.getOwner()==recursive&&!recurseSeen){recurseSeen=true;nested=cast(h,recursive,h.absolutePos(new BlockPos(12,1,24)));}}catch(RuntimeException error){failure=error;}}
    }
    private static final class EmberPulseBoundary{
        final GameTestHelper h;final AshBoneWingUnit first,second;final List<GoldenFoxUnit> victims;final long firstPulse;final int[] attempts=new int[7];boolean cancelSeen,reentrySeen,nestedAccepted,damageReentrySeen,damageNestedAccepted,targetAbaSeen;double nestedLoss,damageNestedLoss;RuntimeException failure;
        EmberPulseBoundary(GameTestHelper h,AshBoneWingUnit first,AshBoneWingUnit second,List<GoldenFoxUnit> victims,long firstPulse){this.h=h;this.first=first;this.second=second;this.victims=victims;this.firstPulse=firstPulse;}
        int lane(LivingEntity victim,DamageSource damage){return AshEmberLanding.isPulse(damage)&&(damage.getEntity()==first||damage.getEntity()==second)?victims.indexOf(victim):-1;}
        @SubscribeEvent(priority=EventPriority.HIGHEST,receiveCanceled=true) public void attack(LivingAttackEvent event){int i=lane(event.getEntity(),event.getSource());if(i<0)return;attempts[i]++;if(i==0&&h.getLevel().getGameTime()==firstPulse){cancelSeen=true;event.setCanceled(true);}}
        @SubscribeEvent(priority=EventPriority.HIGHEST,receiveCanceled=true) public void hurt(LivingHurtEvent event){int i=lane(event.getEntity(),event.getSource());if(i!=1||h.getLevel().getGameTime()!=firstPulse||reentrySeen)return;reentrySeen=true;try{float before=event.getEntity().getHealth();nestedAccepted=event.getEntity().hurt(event.getSource(),100);nestedLoss=before-event.getEntity().getHealth();}catch(RuntimeException error){failure=error;}}
        @SubscribeEvent(priority=EventPriority.HIGHEST,receiveCanceled=true) public void damage(LivingDamageEvent event){int i=lane(event.getEntity(),event.getSource());if(h.getLevel().getGameTime()!=firstPulse)return;try{if(i==2&&!damageReentrySeen){damageReentrySeen=true;float before=event.getEntity().getHealth();damageNestedAccepted=event.getEntity().hurt(event.getSource(),100);damageNestedLoss=before-event.getEntity().getHealth();}else if(i==3&&!targetAbaSeen){targetAbaSeen=true;var target=victims.get(i);String owner=target.getOwnerName();target.setOwnerName(owner+"Temporary");target.setOwnerName(owner);}}catch(RuntimeException error){failure=error;}}

    }
    private static SkillGroundRequest request(AshBoneWingUnit source,BlockPos target){return new SkillGroundRequest(UnitSkill.ASH_EMBER_LANDING,source.getId(),source.getUUID(),source.rts().skills().revision(),target);}
    private static SkillResult cast(GameTestHelper h,AshBoneWingUnit source,BlockPos target){return new SkillNetwork.GroundCast(request(source,target)).execute(player(h,source.getOwnerName()));}
    private static GoldenFoxUnit near(GameTestHelper h,String owner,Vec3 center,double dx,double dz){var origin=h.absolutePos(BlockPos.ZERO);return target(h,owner,center.x+dx-origin.getX(),center.z+dz-origin.getZ());}
    private static void waitPublished(GameTestHelper h,Collection<? extends Entity> bodies){checkProbe();for(var body:bodies)h.assertTrue(body.tickCount>3&&h.getLevel().getEntity(body.getId())==body&&h.getLevel().getEntity(body.getUUID())==body,"actual recipient natural ticks and original dual ID/UUID publication before first pulse");}
