    private static GameTestSequence ready(GameTestHelper h,Entity...entities){
        long[] began={-1};return h.startSequence().thenWaitUntil(()->{
            long now=h.getLevel().getGameTime();if(began[0]<0)began[0]=now;
            for(Entity e:entities){boolean published=e.tickCount>3&&h.getLevel().getEntity(e.getId())==e&&h.getLevel().getEntity(e.getUUID())==e;
                if(!published&&(now-began[0])%10==0){var pos=e.blockPosition();var chunk=new ChunkPos(pos);var actual=h.getLevel().getChunkSource().getChunkNow(chunk.x,chunk.z);System.out.println("ASH_EMBER_READY_WAIT time="+now+" elapsed="+(now-began[0])+" uuid="+e.getUUID()+" ticks="+e.tickCount+" pos="+pos+" full="+(actual==null?"null":actual.getFullStatus())+" entityTicking="+h.getLevel().isPositionEntityTicking(pos)+" entitiesLoaded="+h.getLevel().areEntitiesLoaded(chunk.toLong())+" byId="+(h.getLevel().getEntity(e.getId())==e)+" byUuid="+(h.getLevel().getEntity(e.getUUID())==e));}
                h.assertTrue(published,"actual published IDs UUIDs and natural entity ticks; NoAI does not promise ground: "+e.getUUID());
            }
        }).thenExecute(()->{System.out.println("ASH_EMBER_READY_COMPLETE time="+h.getLevel().getGameTime()+" elapsed="+(h.getLevel().getGameTime()-began[0])+" first="+entities[0].getUUID());h.assertTrue(!com.solegendary.reignofnether.fogofwar.FogOfWarServerEvents.isEnabled(),"actual focused fog-off environment, no fabricated visibility");bank(h);});
    }
