    private static void listen(){if(!listening){MinecraftForge.EVENT_BUS.register(PROBE);listening=true;}}
    private static void observeSource(AshBoneWingUnit source){listen();PROBE.sources.put(source.getUUID(),source);}
    private static Trace watch(LivingEntity target){listen();var trace=new Trace(target);if(PROBE.traces.put(target.getUUID(),trace)!=null)throw new IllegalStateException("duplicate exact victim observer");return trace;}
    private static void checkProbe(){if(PROBE.failure!=null)throw PROBE.failure;}
    private static List<EmberLandingProjectile> shots(AshBoneWingUnit source){return PROBE.projectiles.getOrDefault(source.getUUID(),List.of()).stream().filter(p->p.getClass()==EmberLandingProjectile.class).map(p->(EmberLandingProjectile)p).toList();}
    private static List<AshEmberLanding.ZoneView> born(AshBoneWingUnit source){return PROBE.zoneBirths.values().stream().filter(z->z.sourceUuid().equals(source.getUUID())).sorted(Comparator.comparing(z->z.id().toString())).toList();}
    private static AshEmberLanding.ZoneView onlyZone(GameTestHelper h,AshBoneWingUnit source){checkProbe();var zones=born(source);h.assertTrue(zones.size()==1,"one actual zone from real original source: "+zones);return zones.get(0);}
    private static void published(GameTestHelper h,AshBoneWingUnit source){checkProbe();var list=shots(source);h.assertTrue(list.size()==1,"exact one independently constructed skill projectile");var shot=list.get(0);h.assertTrue(!shot.isRemoved()&&shot.getOwner()==source&&h.getLevel().getEntity(shot.getId())==shot&&h.getLevel().getEntity(shot.getUUID())==shot&&AshEmberLanding.flightValid(shot)&&AshEmberLanding.activeFlightCount(source)==1,"actual published ID/UUID/source and committed flight, not observer-granted permission");}
    private static void pulseSource(GameTestHelper h,Hit hit,AshBoneWingUnit source){var d=hit.damage;h.assertTrue(hit.pulse&&AshEmberLanding.isPulse(d)&&d.is(AshEmberLanding.DAMAGE_TYPE)&&d.getEntity()==source&&d.getDirectEntity()==source&&!(d.getDirectEntity() instanceof Projectile),"actual independent fixed-zone magic source uses caster, never a projectile or ordinary proxy");h.assertTrue(d.is(DamageTypeTags.WITCH_RESISTANT_TO)&&d.is(DamageTypeTags.BYPASSES_ARMOR)&&!d.is(DamageTypeTags.IS_PROJECTILE)&&!d.is(DamageTypeTags.BYPASSES_COOLDOWN)&&!d.is(DamageTypeTags.BYPASSES_RESISTANCE)&&!d.is(DamageTypeTags.BYPASSES_EFFECTS)&&!d.is(DamageTypeTags.BYPASSES_INVULNERABILITY)&&!d.is(DamageTypeTags.IS_FIRE)&&!d.is(DamageTypeTags.IS_EXPLOSION),"only approved magic/armor classification, no nativeiframe/defense bypass or fire/explosion role");}
