    private static final class Trace{final LivingEntity target;final List<Hit> hits=new ArrayList<>();Hit pending;Trace(LivingEntity target){this.target=target;}void finish(){if(pending!=null){pending.hpAfter=target.getHealth();pending.absorbAfter=target.getAbsorptionAmount();pending.gelAfter=SkillEffects.shieldRemaining(target);hits.add(pending);System.out.println("ASH_EMBER_ACTUAL_RECEIPT target="+target.getUUID()+" "+pending);pending=null;}}}
    private static final class Hit{final long time;final DamageSource damage;final boolean pulse;final float hpBefore,absorbBefore;final double gelBefore;float hpAfter,absorbAfter;double gelAfter;float eventAmount;boolean sawDamage,canceled;Hit(Trace t,DamageSource damage){time=t.target.level().getGameTime();this.damage=damage;pulse=AshEmberLanding.isPulse(damage);hpBefore=t.target.getHealth();absorbBefore=t.target.getAbsorptionAmount();gelBefore=SkillEffects.shieldRemaining(t.target);}double hpLoss(){return hpBefore-hpAfter;}double absorbLoss(){return absorbBefore-absorbAfter;}double gelLoss(){return gelBefore-gelAfter;}@Override public String toString(){return "time="+time+" pulse="+pulse+" source="+(damage.getEntity()==null?null:damage.getEntity().getUUID())+" HP="+hpBefore+"->"+hpAfter+" absorb="+absorbBefore+"->"+absorbAfter+" Gel="+gelBefore+"->"+gelAfter+" eventAmountDiagnosticOnly="+eventAmount+" canceled="+canceled;}}
    private static final class Probe{
        final Map<UUID,AshBoneWingUnit> sources=new HashMap<>();final Map<UUID,List<Projectile>> projectiles=new HashMap<>();final Map<UUID,Trace> traces=new HashMap<>();final List<JoinRead> joins=new ArrayList<>();final List<ImpactRead> impacts=new ArrayList<>();final List<PositionRead> positions=new ArrayList<>();final Map<UUID,AshEmberLanding.ZoneView> zoneBirths=new LinkedHashMap<>();final List<ZoneRead> zoneReads=new ArrayList<>();final Set<UUID> cancelJoin=new HashSet<>();RuntimeException failure;
        @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public void join(EntityJoinLevelEvent e){if(!(e.getEntity() instanceof Projectile shot)||!(shot.getOwner() instanceof AshBoneWingUnit source)||!sources.containsKey(source.getUUID()))return;try{if(shot.getClass()==EmberLandingProjectile.class&&cancelJoin.remove(source.getUUID()))e.setCanceled(true);projectiles.computeIfAbsent(source.getUUID(),k->new ArrayList<>()).add(shot);var read=new JoinRead(e.getLevel().getGameTime(),shot.getUUID(),source.getUUID(),shot.position(),e.isCanceled());joins.add(read);System.out.println("ASH_EMBER_REAL_JOIN "+read+" type="+shot.getClass().getName());}catch(RuntimeException error){failure=error;}}
        @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public void impact(ProjectileImpactEvent e){if(!(e.getProjectile() instanceof EmberLandingProjectile shot)||!(shot.getOwner() instanceof AshBoneWingUnit source)||!sources.containsKey(source.getUUID()))return;try{var hit=e.getRayTraceResult();var read=new ImpactRead(shot.level().getGameTime(),shot.getUUID(),hit.getType(),hit.getLocation(),hit instanceof EntityHitResult entity?entity.getEntity():null);impacts.add(read);System.out.println("ASH_EMBER_REAL_IMPACT "+read);}catch(RuntimeException error){failure=error;}}
        @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public void attack(LivingAttackEvent e){var t=traces.get(e.getEntity().getUUID());if(t==null||failure!=null)return;try{t.finish();t.pending=new Hit(t,e.getSource());}catch(RuntimeException error){failure=error;}}
        @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public void damage(LivingDamageEvent e){var t=traces.get(e.getEntity().getUUID());if(t!=null&&t.pending!=null&&t.pending.damage==e.getSource()){t.pending.sawDamage=true;t.pending.eventAmount=e.getAmount();t.pending.canceled=e.isCanceled();}}
        @SubscribeEvent(priority=EventPriority.LOWEST) public void end(TickEvent.LevelTickEvent e){if(e.phase!=TickEvent.Phase.END||!(e.level instanceof ServerLevel level)||failure!=null)return;try{for(var t:traces.values())if(t.target.level()==level)t.finish();for(var list:projectiles.values())for(var shot:list)if(shot.level()==level&&!shot.isRemoved())positions.add(new PositionRead(level.getGameTime(),shot.getUUID(),shot.position(),level.getEntity(shot.getId())==shot,level.getEntity(shot.getUUID())==shot));for(var z:AshEmberLanding.zones(level))if(sources.containsKey(z.sourceUuid())){if(zoneBirths.putIfAbsent(z.id(),z)==null)System.out.println("ASH_EMBER_REAL_ZONE_BIRTH "+z);zoneReads.add(new ZoneRead(level.getGameTime(),z));}}catch(RuntimeException error){failure=error;}}
    }
    private record SyncObservation(long gameTime,SkillNetwork.Sync packet){}
    private static List<SyncObservation> syncs(ServerPlayer player,AshBoneWingUnit source){return ((RecordingHandler)player.connection).wire.syncs.stream().filter(p->p.packet().sourceUuid().equals(source.getUUID())&&p.packet().skill()==UnitSkill.ASH_EMBER_LANDING&&p.packet().revision()>=0).toList();}
    /** Local real PlayerList membership, not GUI/socket login simulation or direct state.sync. */
    @SuppressWarnings("unchecked") private static void syncMembership(ServerPlayer player,boolean present){try{var list=player.serverLevel().getServer().getPlayerList();var players=net.minecraft.server.players.PlayerList.class.getDeclaredField("players");var byId=net.minecraft.server.players.PlayerList.class.getDeclaredField("playersByUUID");players.setAccessible(true);byId.setAccessible(true);List<ServerPlayer> actual=(List<ServerPlayer>)players.get(list);Map<UUID,ServerPlayer> ids=(Map<UUID,ServerPlayer>)byId.get(list);if(present){if(!actual.contains(player))actual.add(player);ids.put(player.getUUID(),player);SYNC_MEMBERS.add(player);}else{actual.remove(player);ids.remove(player.getUUID(),player);SYNC_MEMBERS.remove(player);}}catch(ReflectiveOperationException error){throw new RuntimeException("real local PlayerList membership",error);}}
    private static final class RecordingHandler extends ServerGamePacketListenerImpl {
        final RecordingConnection wire;RecordingHandler(ServerPlayer p){this(p,new RecordingConnection(p.serverLevel()));}private RecordingHandler(ServerPlayer p,RecordingConnection wire){super(p.serverLevel().getServer(),wire,p);this.wire=wire;}
        @Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){wire.send(p);}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){wire.send(p,listener);}
    }
    private static final class RecordingConnection extends net.minecraft.network.Connection {
        final ServerLevel level;final List<SyncObservation> syncs=new ArrayList<>();RecordingConnection(ServerLevel level){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);this.level=level;}
        @Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){record(p);}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){record(p);}
        private void record(net.minecraft.network.protocol.Packet<?> packet){if(packet instanceof net.minecraft.network.protocol.game.ClientboundCustomPayloadPacket payload&&payload.getIdentifier().equals(DreamseekersMod.id("unit_skills"))){var bytes=new FriendlyByteBuf(payload.getData().copy());try{if(bytes.readVarInt()==1){var sync=SkillNetwork.Sync.decode(bytes);if(bytes.readableBytes()!=0)throw new IllegalStateException("trailing real Sync payload");syncs.add(new SyncObservation(level.getGameTime(),sync));}}finally{bytes.release();}}}
    }
    private static final class SilentHandler extends ServerGamePacketListenerImpl {SilentHandler(ServerPlayer p){super(p.serverLevel().getServer(),new SilentConnection(),p);}@Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){}}
    private static final class SilentConnection extends net.minecraft.network.Connection {SilentConnection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}@Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){}}
